Created by **Wataru Hirayama**, 3rd Apr 2013. _(originally [Lighthouse ticket #3736](http://cakephp.lighthouseapp.com/projects/42648/tickets/3736))_:

---
#### What I did

When I post a https request to HttpSocket which is configProxy'ed, false response was returned.
#### What happened

HttpSocket seems not to post CONNECT request to proxy server.
#### What I expected to happen

Here's my quick hack against 2.2.5 source.

``` diff
--- a/local/lib/Cake/Network/CakeSocket.php     Fri Mar 29 16:42:39 2013 +0900
+++ b/local/lib/Cake/Network/CakeSocket.php     Wed Apr 03 12:22:33 2013 +0900
@@ -101,7 +101,7 @@
                }

                $scheme = null;
-               if (isset($this->config['request']) && $this->config['request']['uri']['scheme'] == 'https') {
+               if (isset($this->config['request']) && $this->config['request']['uri']['scheme'] == 'https' && !isset($this->config['proxy'])) {
                        $scheme = 'ssl://';
                }

@@ -122,6 +122,35 @@
                if ($this->connected) {
                        stream_set_timeout($this->connection, $this->config['timeout']);
                }
+
+               if (isset($this->config['request']) && $this->config['request']['uri']['scheme'] == 'https' && isset($this->config['proxy'])) {
+                 $req = array();
+                 $req[] =
+                   'CONNECT '. $this->config['request']['uri']['host'] .
+                   ':' . $this->config['request']['uri']['port'] . ' HTTP/1.1';
+                 $req[] = 'Host: ' . $this->config['host'];
+                 $req[] = 'User-Agent: php proxy';
+
+                 fwrite($this->connection, implode("\r\n", $req)."\r\n\r\n");
+
+                 while(true){
+                   $s = rtrim(fgets($this->connection, 4096));
+                   if(preg_match('/^$/', $s)){
+                      break;
+                   }
+                 }
+
+                 $modes = array(STREAM_CRYPTO_METHOD_TLS_CLIENT,
+                                STREAM_CRYPTO_METHOD_SSLv3_CLIENT,
+                                STREAM_CRYPTO_METHOD_SSLv23_CLIENT,
+                                STREAM_CRYPTO_METHOD_SSLv2_CLIENT);
+                 $success = false;
+                 foreach($modes as $mode) {
+                   $success = stream_socket_enable_crypto($this->connection, true, $mode);
+                   if ($success) break;
+                 }
+               }
+
                return $this->connected;
        }

diff -r b00345ea0efb -r 15f16bd13616 local/lib/Cake/Network/Http/HttpSocket.php
--- a/local/lib/Cake/Network/Http/HttpSocket.php        Fri Mar 29 16:42:39 2013 +0900
+++ b/local/lib/Cake/Network/Http/HttpSocket.php        Wed Apr 03 12:22:33 2013 +0900
@@ -596,6 +596,7 @@
                }
                $this->config['host'] = $this->_proxy['host'];
                $this->config['port'] = $this->_proxy['port'];
+               $this->config['proxy'] = true;

                if (empty($this->_proxy['method']) || !isset($this->_proxy['user'], $this->_proxy['pass'])) {
